package com.littlemakers.village.nativeapp;
import android.opengl.*;import java.nio.*;

/** Shared original rabbit, fox and bear VBOs with coat detail, small glossy eyes and quiet breathing. */
final class WildlifeRenderer {
 private static final String VS="uniform mat4 uMvp;uniform mat3 uNormal;uniform float uTime;attribute vec3 aPosition;attribute vec3 aNormal;attribute vec3 aColor;attribute float aSkin;varying vec3 vP;varying vec3 vN;varying vec3 vColor;varying float vSkin;void main(){vec3 p=aPosition;float breath=1.+sin(uTime*2.)*.009;p.z*=breath;vN=normalize(uNormal*vec3(aNormal.xy,aNormal.z/breath));vP=aPosition;vColor=aColor;vSkin=aSkin;gl_Position=uMvp*vec4(p,1.);}";
 private static final String FS="precision mediump float;varying vec3 vP;varying vec3 vN;varying vec3 vColor;varying float vSkin;void main(){vec3 n=normalize(vN);vec3 l=normalize(vec3(-.45,-.65,1.));float d=max(dot(n,l),0.);float grain=.5+.5*sin(vP.x*149.+vP.y*31.+sin(vP.z*92.)*2.);float strand=.5+.5*sin(vP.y*113.+sin(vP.x*23.)*3.);float coat=vSkin<.5?.88+.07*grain+.05*strand:1.;float spec=pow(max(dot(n,normalize(l+vec3(0.,0.,1.))),0.),vSkin>.5&&vSkin<1.5?62.:18.);float rim=pow(1.-abs(n.z),3.)*(vSkin<.5?.065:0.);vec3 color=vColor*coat*(.43+.57*d)+vec3(spec*(vSkin>.5&&vSkin<1.5?.32:.025)+rim);gl_FragColor=vec4(clamp(color,0.,1.),1.);}";
 private int program,pos,normal,color,skin,mvpU,normalU,timeU;private final int[]buffers=new int[3],counts=new int[3];
 private final float[]mvp=new float[16],inverse=new float[16],normals=new float[9];
 private int shader(int type,String code){int id=GLES20.glCreateShader(type);GLES20.glShaderSource(id,code);GLES20.glCompileShader(id);int[]ok={0};GLES20.glGetShaderiv(id,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetShaderInfoLog(id));return id;}
 void create(){int v=shader(GLES20.GL_VERTEX_SHADER,VS),f=shader(GLES20.GL_FRAGMENT_SHADER,FS);program=GLES20.glCreateProgram();GLES20.glAttachShader(program,v);GLES20.glAttachShader(program,f);GLES20.glLinkProgram(program);GLES20.glDeleteShader(v);GLES20.glDeleteShader(f);int[]ok={0};GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(program));pos=GLES20.glGetAttribLocation(program,"aPosition");normal=GLES20.glGetAttribLocation(program,"aNormal");color=GLES20.glGetAttribLocation(program,"aColor");skin=GLES20.glGetAttribLocation(program,"aSkin");mvpU=GLES20.glGetUniformLocation(program,"uMvp");normalU=GLES20.glGetUniformLocation(program,"uNormal");timeU=GLES20.glGetUniformLocation(program,"uTime");GLES20.glGenBuffers(3,buffers,0);}
 private void upload(int species){float[]mesh=WildlifeGeometry.build(species);counts[species]=mesh.length/WildlifeGeometry.STRIDE;FloatBuffer data=ByteBuffer.allocateDirect(mesh.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();data.put(mesh).position(0);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,buffers[species]);GLES20.glBufferData(GLES20.GL_ARRAY_BUFFER,mesh.length*4,data,GLES20.GL_STATIC_DRAW);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,0);}
 void draw(int species,float[]vp,float[]model,float seconds){if(species<0||species>=3||program==0||!Matrix.invertM(inverse,0,model,0))return;if(counts[species]==0)upload(species);Matrix.multiplyMM(mvp,0,vp,0,model,0);for(int c=0;c<3;c++)for(int r=0;r<3;r++)normals[c*3+r]=inverse[r*4+c];GLES20.glUseProgram(program);GLES20.glUniformMatrix4fv(mvpU,1,false,mvp,0);GLES20.glUniformMatrix3fv(normalU,1,false,normals,0);GLES20.glUniform1f(timeU,seconds);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,buffers[species]);GLES20.glEnableVertexAttribArray(pos);GLES20.glEnableVertexAttribArray(normal);GLES20.glEnableVertexAttribArray(color);GLES20.glEnableVertexAttribArray(skin);GLES20.glVertexAttribPointer(pos,3,GLES20.GL_FLOAT,false,40,0);GLES20.glVertexAttribPointer(normal,3,GLES20.GL_FLOAT,false,40,12);GLES20.glVertexAttribPointer(color,3,GLES20.GL_FLOAT,false,40,24);GLES20.glVertexAttribPointer(skin,1,GLES20.GL_FLOAT,false,40,36);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,counts[species]);GLES20.glDisableVertexAttribArray(color);GLES20.glDisableVertexAttribArray(skin);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,0);}
}
